// Rebuilds one purchase-day fill-draw craps battle from its chain events, off the main thread.
// Pure: no RPC. `replayCoinDrawBattle` (database/src/craps/coin-draw.ts, vendored into
// craps-engine.js) recovers the unlogged chip and FAILS CLOSED unless every run's ending
// bankroll, roll count and paid figure — and the pot's winner and reach — match the events.
import { replayCoinDrawBattle, coinDrawWordForDay, LEG_ORDER } from './craps-engine.js';

const text = value => String(value);

/** Serializable replay: every figure a decimal wei string, every run's dice and coins included. */
export function materializeCoinDrawBattle(input) {
  const word = coinDrawWordForDay(BigInt(input.dayWord), Number(input.level));
  return serializeCoinDrawReplay(replayCoinDrawBattle({ word, runs: input.runs, pot: input.pot }));
}

/** A verified `replayCoinDrawBattle` result as plain JSON-safe data. */
export function serializeCoinDrawReplay(replay) {
  return {
    word: text(replay.word), chipFlip: text(replay.chipFlip), bankrollWei: text(replay.bankroll), goalWei: text(replay.goal),
    units: text(replay.units), stakesMinWei: text(replay.stakesMin), stakesMaxWei: replay.stakesMax == null ? null : text(replay.stakesMax),
    winnerIndex: replay.winnerIndex, potWei: text(replay.pot),
    runs: replay.runs.map(run => ({
      index: run.index, player: run.player, units: text(run.units), rank: run.rank, isWinner: run.isWinner, stop: run.stop,
      // Whole FLIP per leg, in the contract's leg order.
      board: Object.fromEntries(LEG_ORDER.map(leg => [leg, text(run.board[leg])])),
      bankrollInWei: text(run.bankrollIn), goalWei: text(run.goal), bankrollOutWei: text(run.result.bankrollOut),
      peakWei: text(run.result.peakBankroll), outWei: text(run.out), paidWei: text(run.paid),
      handsPlayed: run.result.handsPlayed, totalRolls: run.result.totalRolls,
      ladderWei: run.result.ladder.map(text),
      hands: run.trace.hands.map(hand => hand.map(roll => [roll.d1, roll.d2])),
      survivals: run.trace.survivals.map(entry => ({ shooter: entry.shooter, survived: entry.survived })),
    })),
  };
}

if (typeof self !== 'undefined' && typeof document === 'undefined') self.onmessage = ({ data }) => {
  try { self.postMessage({ replay: materializeCoinDrawBattle(data) }); }
  catch (error) { self.postMessage({ error: error.message, code: error.code ?? null }); }
};
